<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class UpbringingExtendedController extends Controller{
private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('head_academic')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('curator'),403);}
public function councils(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('prevention_councils')->where('academic_period_id',$p->id)->orderByDesc('meeting_on')->get();$cases=DB::table('student_support_cases as c')->join('students as s','s.id','=','c.student_id')->where('c.academic_period_id',$p->id)->where('c.status','!=','closed')->select('c.id','c.reason','s.last_name','s.first_name')->get();return view('upbringing.councils',compact('rows','cases'));}
public function councilStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['protocol_number'=>'required|string|max:100','meeting_on'=>'required|date','agenda'=>'nullable|string|max:5000']);DB::table('prevention_councils')->insert($d+['academic_period_id'=>$p->id,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function councilUpdate(Request $r,$id){$this->ok($r);$x=DB::table('prevention_councils')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['protocol_number'=>'required|string|max:100','meeting_on'=>'required|date','agenda'=>'nullable|string|max:5000']);DB::table('prevention_councils')->where('id',$id)->update($d+['updated_at'=>now()]);return back();}
public function councilArchive(Request $r,$id){$this->ok($r);$x=DB::table('prevention_councils')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('prevention_councils')->where('id',$id)->update(['archived_at'=>now(),'updated_at'=>now()]);return back();}
public function councilCase(Request $r,$id){$this->ok($r);$c=DB::table('prevention_councils')->find($id);abort_if(!$c,404);PeriodGuard::writable($c->academic_period_id);$d=$r->validate(['student_support_case_id'=>'required|exists:student_support_cases,id','decision'=>'required|string|max:5000','control_on'=>'nullable|date']);DB::table('prevention_council_cases')->updateOrInsert(['prevention_council_id'=>$id,'student_support_case_id'=>$d['student_support_case_id']],['decision'=>$d['decision'],'control_on'=>$d['control_on']??null,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function social(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get()->map(function($g){$ids=DB::table('students')->where(['current_group_id'=>$g->id,'status'=>'active'])->pluck('id');$g->student_count=$ids->count();$g->social_support_count=DB::table('student_social_statuses')->whereIn('student_id',$ids)->where('status','active')->where(fn($q)=>$q->whereNull('valid_until')->orWhere('valid_until','>=',today()))->distinct()->count('student_id');$g->categories=DB::table('student_social_statuses as ss')->join('student_social_categories as sc','sc.id','=','ss.category_id')->whereIn('ss.student_id',$ids)->where('ss.status','active')->where(fn($q)=>$q->whereNull('ss.valid_until')->orWhere('ss.valid_until','>=',today()))->select('sc.name',DB::raw('count(distinct ss.student_id) total'))->groupBy('sc.id','sc.name')->orderByDesc('total')->get();return $g;});return view('upbringing.social',compact('groups'));}
public function clubs(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$rows=DB::table('student_clubs')->where('academic_period_id',$p->id)->orderBy('title')->get();$students=DB::table('students')->where('status','active')->orderBy('last_name')->get();return view('upbringing.clubs',compact('rows','students'));}
public function clubStore(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');PeriodGuard::writable($p->id);$d=$r->validate(['type'=>'required|in:club,section,student_government,volunteer','title'=>'required|string|max:255','description'=>'nullable|string|max:3000','schedule'=>'nullable|string|max:255','place'=>'nullable|string|max:255']);DB::table('student_clubs')->insert($d+['academic_period_id'=>$p->id,'leader_user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function clubUpdate(Request $r,$id){$this->ok($r);$x=DB::table('student_clubs')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['type'=>'required|in:club,section,student_government,volunteer','title'=>'required|string|max:255','description'=>'nullable|string|max:3000','schedule'=>'nullable|string|max:255','place'=>'nullable|string|max:255']);DB::table('student_clubs')->where('id',$id)->update($d+['updated_at'=>now()]);return back();}
public function clubArchive(Request $r,$id){$this->ok($r);$x=DB::table('student_clubs')->find($id);abort_if(!$x,404);PeriodGuard::writable($x->academic_period_id);DB::table('student_clubs')->where('id',$id)->update(['active'=>0,'updated_at'=>now()]);return back();}
public function clubMember(Request $r,$club){$this->ok($r);$x=DB::table('student_clubs')->find($club);PeriodGuard::writable($x->academic_period_id);$d=$r->validate(['student_id'=>'required|exists:students,id','role'=>'required|string|max:100']);DB::table('student_club_members')->updateOrInsert(['student_club_id'=>$club,'student_id'=>$d['student_id']],['role'=>$d['role'],'joined_on'=>today(),'left_on'=>null,'updated_at'=>now(),'created_at'=>now()]);return back();}
public function signals(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$att=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->groupBy('a.student_id')->select('a.student_id',DB::raw('COUNT(*) total'),DB::raw("SUM(CASE WHEN a.status IN ('absent','late') THEN 1 ELSE 0 END) concerns"))->get()->keyBy('student_id');$gr=DB::table('grade_records as g')->join('lesson_occurrences as l','l.id','=','g.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->whereRaw("g.value REGEXP '^[0-9]+([.][0-9]+)?$'")->groupBy('g.student_id')->select('g.student_id',DB::raw('AVG(CAST(g.value AS DECIMAL(5,2))) avg_grade'),DB::raw("SUM(CASE WHEN CAST(g.value AS DECIMAL(5,2))<=2 THEN 1 ELSE 0 END) low_count"))->get()->keyBy('student_id');$students=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->join('study_groups as sg','sg.id','=','m.study_group_id')->where('m.academic_period_id',$p->id)->where('m.status','active')->select('s.id','s.last_name','s.first_name','sg.name as group_name')->get();$rows=$students->map(function($s)use($att,$gr){$a=$att->get($s->id);$g=$gr->get($s->id);$s->attendance_concerns=$a?intval($a->concerns):0;$s->attendance_total=$a?intval($a->total):0;$s->avg_grade=$g?round($g->avg_grade,2):null;$s->low_count=$g?intval($g->low_count):0;$s->signal=($s->attendance_total&&$s->attendance_concerns/$s->attendance_total>=.2)||$s->low_count>=3;return $s;})->filter(fn($x)=>$x->signal)->values();return view('upbringing.signals',compact('rows'));}
}